mapper.select:

/* selectCommonMpIvDlvryDetailPopInfo */
SELECT	INV_NO,
			INV_DATE
FROM	ICOMIVHD
WHERE	1=1
AND		BUYER = #{buyer}
AND		INV_NO = #{inv_no}

UNION

SELECT	INV_NO,
			INV_DATE
FROM	WMSIVDT
WHERE	1=1
AND		BUYER = #{buyer}
AND		INV_NO = #{inv_no}

/* selectCommonMpIvDlvryDetailPopList */ SELECT PODT.REF_PR_NO AS REF_PR_NO, IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO, IVDT.DESCRIPTION AS DESCRIPTION, IVDT.SPECIFICATION AS SPECIFICATION, PODT.MAKER_NAME AS MAKER_NAME, IVDT.UNIT_PRICE AS UNIT_PRICE, IVDT.ITEM_AMT AS ITEM_AMT, PODT.ITEM_QTY AS ITEM_QTY, PODT.UNIT_MEASURE AS UNIT_MEASURE, IVDT.INV_QTY AS INV_QTY, POHD.PO_REMARK AS REMARK, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION FROM ICOMPODT PODT, ICOMPOHD POHD, ICOMIVDT IVDT WHERE 1=1 AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND IVDT.BUYER = #{buyer} AND IVDT.INV_NO = #{inv_no}
UNION
SELECT PODT.REF_PR_NO AS REF_PR_NO, IVDT.BUYER_ITEM_NO AS BUYER_ITEM_NO, IVDT.DESCRIPTION AS DESCRIPTION, IVDT.SPECIFICATION AS SPECIFICATION, PODT.MAKER_NAME AS MAKER_NAME, IVDT.UNIT_PRICE AS UNIT_PRICE, IVDT.UNIT_AMT AS ITEM_AMT, PODT.ITEM_QTY AS ITEM_QTY, PODT.UNIT_MEASURE AS UNIT_MEASURE, IVDT.INV_QTY AS INV_QTY, POHD.PO_REMARK AS REMARK, POHD.DELY_TO_LOCATION AS DELY_TO_LOCATION FROM ICOMPODT PODT, ICOMPOHD POHD, WMSIVDT IVDT WHERE 1=1 AND PODT.BUYER = IVDT.BUYER AND PODT.PO_NO = IVDT.PO_NO AND PODT.PO_SEQ = IVDT.PO_SEQ AND PODT.BUYER = POHD.BUYER AND PODT.PO_NO = POHD.PO_NO AND PODT.STATUS <> 'D' AND POHD.STATUS <> 'D' AND IVDT.STATUS <> 'D' AND IVDT.BUYER = #{buyer} AND IVDT.INV_NO = #{inv_no}
